package com.akira.one;
import android.os.Bundle;import android.util.Base64;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import org.json.*;import java.nio.charset.StandardCharsets;
public class EpgActivity extends BaseActivity{protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_epg);String id=getIntent().getStringExtra("stream_id"),title=getIntent().getStringExtra("title");((TextView)findViewById(R.id.epgTitle)).setText(title==null?"Programação":title);TextView body=findViewById(R.id.epgBody);body.setText("Carregando programação...");XtreamClient.getShortEpg(this,id,new XtreamClient.ObjectCallback(){public void onSuccess(JSONObject o){JSONArray a=o.optJSONArray("epg_listings");if(a==null)a=o.optJSONArray("epg_list");StringBuilder s=new StringBuilder();if(a!=null)for(int i=0;i<a.length();i++){JSONObject e=a.optJSONObject(i);if(e==null)continue;s.append(e.optString("start","--:--")).append("  ").append(decode(e.optString("title","Sem título"))).append("\n");String d=decode(e.optString("description",""));if(!d.isBlank())s.append(d).append("\n");s.append("\n");}body.setText(s.length()==0?"Nenhuma programação disponível para este canal.":s.toString());}public void onError(Exception e){body.setText("EPG indisponível: "+e.getMessage());}});}private String decode(String v){if(v==null||v.isBlank())return "";try{byte[] b=Base64.decode(v,Base64.DEFAULT);String s=new String(b,StandardCharsets.UTF_8);if(s.chars().filter(ch->ch<32&&ch!='\n'&&ch!='\r'&&ch!='\t').count()>2)return v;return s;}catch(Exception e){return v;}}}
